<script setup lang="ts">
import {computed,nextTick,onBeforeUnmount,ref,watch} from 'vue'
import {BookOpen,Plus,FolderOpen,Maximize,Minimize,Search} from 'lucide-vue-next'
import type {GameItem,LinkedFile} from '@/types'
import type {GamePreview} from '@/types/game-workspace'
import type {GameLinkState} from '@/types/game-project'
import {errorMessage,formatBytes,plain,LINK_TYPE_LABEL} from '@/utils'
import {useToast} from '@/composables/useToast'
import {markdownLines} from '@/utils/game-notes'
import GameMarkdown from './GameMarkdown.vue'
import {gameDocumentGroup,projectOf} from '@/utils/game-project'
import LibraryToolbarMenu from '@/components/library/LibraryToolbarMenu.vue'
const props=defineProps<{game:GameItem;initialPath?:string}>(),emit=defineEmits<{updated:[game:GameItem]}>(),{error}=useToast()
const links=computed(()=>props.game.linked_files.filter(f=>f.type==='guide')),query=ref(''),selected=ref(''),doc=ref<GamePreview>(),states=ref<GameLinkState[]>([]),loading=ref(false),failure=ref(''),full=ref(false),busy=ref(false)
const current=computed(()=>links.value.find(f=>f.path===selected.value)),visible=computed(()=>links.value.filter(f=>(f.label+' '+f.path).toLowerCase().includes(query.value.toLowerCase())))
const groups=computed(()=>[{id:'start',label:'从这里开始'},{id:'guide',label:'攻略与说明'},{id:'record',label:'精修与核查记录'}].map(group=>({...group,files:visible.value.filter(f=>gameDocumentGroup(f,projectOf(props.game)?.guidePath)===group.id)})).filter(group=>group.files.length))
const reader=ref<HTMLElement>(),markdown=ref<InstanceType<typeof GameMarkdown>>(),headings=computed(()=>doc.value?.kind==='md'?markdownLines(doc.value.text).headings:[])
let generation=0,disposed=false,timer:ReturnType<typeof setTimeout>|undefined,pending:{id:string;file:LinkedFile;progress:number}|undefined,saving:Promise<void>|null=null
const exists=(f:LinkedFile)=>states.value.find(s=>s.path===f.path)?.exists
function rebaseProgress(file:LinkedFile,updated:GameItem){if(pending?.file.path===file.path&&JSON.stringify(pending.file)===JSON.stringify(file)){const fresh=updated.linked_files.find(f=>f.path===file.path);if(fresh)pending.file=plain(fresh)}}
async function saveProgress(){clearTimeout(timer);if(saving){await saving;return saveProgress()}const p=pending;if(!p)return;pending=undefined;saving=(async()=>{try{const updated=await window.baoyi.game.patchLink(p.id,p.file.path,{read_progress:p.progress},JSON.stringify(p.file));if(updated){rebaseProgress(p.file,updated);emit('updated',updated)}}catch(e){if(!disposed)error(errorMessage(e))}})();await saving;saving=null}
function scrolled(){if(!reader.value||!current.value||loading.value)return;const el=reader.value,range=el.scrollHeight-el.clientHeight;if(range<1)return;const progress=Math.min(1,Math.max(0,el.scrollTop/range));pending={id:props.game.id,file:plain(current.value),progress};clearTimeout(timer);timer=setTimeout(()=>void saveProgress(),600)}
async function read(file:LinkedFile){await saveProgress();const n=++generation;selected.value=file.path;doc.value=undefined;failure.value='';loading.value=true;try{const result=await window.baoyi.game.previewLink(props.game.id,file.path);if(n===generation){doc.value=result;await nextTick();if(reader.value)reader.value.scrollTop=0}}catch(e){if(n===generation)failure.value=errorMessage(e)}finally{if(n===generation)loading.value=false}}
function resume(){if(reader.value&&current.value)reader.value.scrollTop=(reader.value.scrollHeight-reader.value.clientHeight)*(current.value.read_progress||0)}
async function open(reveal=false){if(!current.value)return;try{const r=await(reveal?window.baoyi.game.revealLink:window.baoyi.game.openLink)(props.game.id,current.value.path);if(!r.ok)error(r.message)}catch(e){error(errorMessage(e))}}
async function add(){busy.value=true;try{const result=await window.baoyi.game.pickLinks(props.game.id,'file','guide');if(result)emit('updated',result)}catch(e){error(errorMessage(e))}finally{busy.value=false}}
async function patch(value:Partial<LinkedFile>|null){await saveProgress();if(!current.value)return;busy.value=true;try{const result=await window.baoyi.game.patchLink(props.game.id,current.value.path,plain(value),JSON.stringify(current.value));if(result)emit('updated',result)}catch(e){error(errorMessage(e))}finally{busy.value=false}}
watch(()=>props.game.id+JSON.stringify(props.game.linked_files),async()=>{const id=props.game.id;try{const result=await window.baoyi.game.linkStates(id);if(!disposed&&props.game.id===id)states.value=result}catch(e){if(!disposed)error(errorMessage(e))}if(!links.value.some(f=>f.path===selected.value)){selected.value='';doc.value=undefined;const first=links.value.find(f=>f.path===props.initialPath)||links.value.find(f=>f.path===projectOf(props.game)?.guidePath)||links.value[0];if(first)void read(first)}},{immediate:true})
onBeforeUnmount(()=>{disposed=true;generation++;void saveProgress()})
</script>
<template>
 <section class="docs-panel" :class="{'docs-panel--full':full}" aria-label="攻略阅读"><aside class="docs-nav"><header><label><Search :size="14"/><input v-model="query" aria-label="搜索攻略与说明" placeholder="搜索攻略与说明"/></label><button class="btn btn--icon" :disabled="busy||game.linked_files.length>=20" aria-label="关联资料" @click="add"><Plus :size="16"/></button></header><p v-if="!links.length" class="empty">还没有攻略。关联 Markdown、TXT、XLSX 或其他本地资料。</p><p v-if="links.length&&!visible.length" class="empty">没有匹配的资料，试试其他关键词。</p><section v-for="group in groups" :key="group.id" class="doc-group"><h4>{{group.label}} <small>{{group.files.length}}</small></h4><button v-for="f in group.files" :key="f.path" class="doc-item" :class="{selected:selected===f.path}" @click="read(f)"><BookOpen :size="18"/><span><strong>{{f.label}}</strong><small>{{f.path.split('.').pop()?.toUpperCase()}} · {{exists(f)===false?'文件缺失':f.read_progress?'读到 '+Math.round(f.read_progress*100)+'%':'未阅读'}}</small><i v-if="f.read_progress" class="progress"><i :style="{width:f.read_progress*100+'%'}"/></i></span></button></section></aside>
 <article class="docs-main"><header v-if="current"><div><h3>{{current.label}}</h3><small>{{doc?formatBytes(doc.bytes):''}} {{doc?.truncated?'· 仅显示预览范围':''}}</small></div><button v-if="current.read_progress" class="btn btn--subtle" @click="resume">继续阅读</button><button class="btn btn--icon" :aria-label="full?'退出全屏阅读':'全屏阅读'" @click="full=!full"><component :is="full?Minimize:Maximize" :size="15"/></button><button class="btn btn--ghost" :disabled="!exists(current)" @click="open()">系统打开</button><button class="btn btn--icon" :disabled="!exists(current)" aria-label="定位资料" @click="open(true)"><FolderOpen :size="15"/></button><LibraryToolbarMenu icon="more" label="管理资料"><label>名称<input :value="current.label" :disabled="busy" @change="patch({label:($event.target as HTMLInputElement).value})"/></label><label>类型<select :value="current.type" :disabled="busy" @change="patch({type:($event.target as HTMLSelectElement).value as LinkedFile['type']})"><option v-for="(label,key) in LINK_TYPE_LABEL" :key="key" :value="key">{{label}}</option></select></label><button :disabled="busy" @click="patch(null)">解除关联，保留文件</button></LibraryToolbarMenu></header>
 <nav v-if="headings.length" class="doc-chapters" aria-label="攻略章节"><button v-for="(h,i) in headings" :key="i" @click="markdown?.jump(i)">{{h.text}}</button></nav><div ref="reader" class="doc-reader" @scroll="scrolled"><p v-if="loading" role="status">读取中…</p><p v-else-if="failure" role="alert">{{failure}}</p><template v-else-if="doc"><GameMarkdown v-if="doc.kind==='md'" ref="markdown" :text="doc.text"/><pre v-else-if="doc.kind==='txt'">{{doc.text}}</pre><template v-else-if="doc.kind==='xlsx'"><p class="sheet-names">{{doc.sheets?.join(' · ')}}（预览第一张表，最多 50 行 / 50 列）</p><table><tbody><tr v-for="(row,i) in doc.rows" :key="i"><th>{{i+1}}</th><td v-for="(cell,j) in row" :key="j">{{cell}}</td></tr></tbody></table></template><p v-else class="empty">此格式暂不支持内嵌预览，请使用系统程序打开。</p><p v-if="doc.truncated" class="preview-limit">已达到预览上限，完整内容请使用系统程序打开。</p></template><p v-else class="empty">选择左侧资料开始阅读</p></div></article></section>
</template>
<style scoped>
.docs-panel{height:clamp(540px,72vh,900px);display:flex;border:1px solid var(--card-border);border-radius:12px;background:var(--bg-card);overflow:hidden}.docs-panel--full{position:fixed;inset:48px 16px 16px;z-index:60;height:auto;box-shadow:0 0 0 100vmax #0009}.docs-nav{width:290px;flex:none;border-right:1px solid var(--divider);padding:12px;overflow:auto}.docs-nav header{display:flex;gap:6px;margin-bottom:12px}.docs-nav label{display:flex;gap:8px;align-items:center;min-width:0;color:var(--text-faint);background:var(--bg-main);padding:6px 9px;border-radius:5px}.docs-nav input{width:100%;min-width:0;background:none;border:0;font-size:12px}.doc-item{display:flex;align-items:flex-start;gap:10px;padding:14px 10px;width:100%;text-align:left;border-radius:7px}.doc-item.selected{background:var(--active-surface)}.doc-item>svg{color:var(--accent-ink);flex:none}.doc-item>span{min-width:0;flex:1}.doc-item strong{display:block;font-size:12px;font-weight:500;overflow-wrap:anywhere}.doc-item small{display:block;font-size:10px;color:var(--text-faint);margin-top:7px}.progress{height:3px;display:block;background:var(--divider);margin-top:9px;border-radius:3px}.progress i{display:block;height:100%;background:var(--accent)}.docs-main{flex:1;min-width:0;display:flex;flex-direction:column}.docs-main>header{display:flex;align-items:center;padding:16px 20px;gap:8px;border-bottom:1px solid var(--divider)}.docs-main>header>div:first-child{flex:1;min-width:0}.docs-main h3{font-size:14px;overflow-wrap:anywhere}.docs-main small{font-size:10px;color:var(--text-faint)}.doc-chapters{display:flex;gap:7px;flex-wrap:wrap;padding:12px 24px;border-bottom:1px solid var(--divider);max-height:95px;overflow:auto}.doc-chapters button{border:1px solid var(--divider-strong);border-radius:5px;padding:4px 8px;font-size:11px;color:var(--text-sub)}.doc-reader{flex:1;min-height:0;overflow:auto;padding:24px 30px}.doc-reader pre{white-space:pre-wrap;overflow-wrap:anywhere;font:12px/1.9 var(--font-mono);user-select:text}table{border-collapse:collapse;user-select:text}td,th{border:1px solid var(--divider-strong);padding:8px 12px;font-size:12px;min-width:60px;max-width:400px;overflow-wrap:anywhere}th{color:var(--text-faint);min-width:30px}.sheet-names,.preview-limit{font-size:11px;color:var(--text-faint);margin-bottom:14px}.empty{font-size:12px;color:var(--text-faint);padding:35px 15px;line-height:1.8}@media(max-width:1100px){.docs-nav{width:220px}.docs-main>header{flex-wrap:wrap}.doc-reader{padding:18px}}
.doc-group{margin:16px 0}.doc-group h4{display:flex;justify-content:space-between;padding:0 10px 7px;font-size:11px;color:var(--text-faint);font-weight:500}.doc-group h4 small{font-weight:400}.doc-reader :deep(.game-markdown){max-width:850px;margin:0 auto}.docs-nav .empty{padding:20px 10px}
</style>
